import re
CHN_DIGIT_MAP = {'零': 0, '一': 1, '二': 2, '三': 3, '四': 4, '五': 5, '六': 6, '七': 7, '八': 8, '九': 9, '十': 10, '百': 100, '佰': 100, '千': 1000, '仟': 1000, '万': 10000, '亿': 100000000}
SCORE_FEATURE_STR = '分之'
DECIMAL_FEATURE_STR = '点'
def hasdigit(input_str):
    return bool(re.search('\\d', input_str))
def isdigit(input_str):
    if input_str.isdigit():
        return True
    elif (input_str.find('.') >= 0):
        return True
    return False
def getchnstr(input_str):
    chn_str = ''
    for c in input_str:
        if (c in CHN_DIGIT_MAP.keys() or not c in SCORE_FEATURE_STR):
            if (c in DECIMAL_FEATURE_STR):
                chn_str = (chn_str + c)
            elif (len(chn_str) > 0):
                break
    return chn_str
def chn2arab(chn_str):
    if (hasdigit(chn_str) and chn_str.find(SCORE_FEATURE_STR) < 0):
        return ''.join(filter(isdigit, chn_str))
    elif (hasdigit(chn_str) and chn_str.find(SCORE_FEATURE_STR) >= 0):
        return mix_chn2arab(chn_str)
    elif (chn_str.find(SCORE_FEATURE_STR) > 0):
        return score_chn2arab(chn_str)
    else:
        return direct_chn2arab(chn_str)
def score_chn2arab(chn_str):
    _chn_str = getchnstr(chn_str)
    nPos = _chn_str.find(SCORE_FEATURE_STR)
    denominator = direct_chn2arab(_chn_str[0:nPos])
    numerator = direct_chn2arab(_chn_str[nPos + len(SCORE_FEATURE_STR):])
    if (denominator != 0):
        result = str(numerator / denominator)
    else:
        result = ''
    return result
def mix_chn2arab(chn_str):
    _chn_str = getchnstr(chn_str)
    nPos = _chn_str.find(SCORE_FEATURE_STR)
    denominator = direct_chn2arab(_chn_str[0:nPos])
    numerator = ''.join(filter(isdigit, chn_str))
    if (denominator != 0):
        result = str(float(numerator) / denominator)
    else:
        result = ''
    return result
