    total = 0
    total_integer = 0
    total_decimal = 0
    chn_str_integer = ''
    chn_str_decimal = ''
    nPos = chn_str.find(DECIMAL_FEATURE_STR)
    if (nPos < 0):
        chn_str_integer = chn_str
